package quebec.culture.donnees;
import android.app.*;import android.os.*;import android.widget.*;import java.util.*;
public class SectorGuideActivity extends Activity{@Override public void onCreate(Bundle b){super.onCreate(b);Ui.bars(this);String s=getIntent().getStringExtra("sector");DataNormalizer.Sector sec;try{sec=DataNormalizer.Sector.valueOf(s);}catch(Exception e){sec=DataNormalizer.Sector.METAMUSIQUE;}LinearLayout r=Ui.root(this);r.addView(Ui.text(this,sec.label,28,true));r.addView(Ui.text(this,"Profil de préparation intégré à l’application. Vérifiez toujours la documentation normative officielle applicable avant de soumettre ou publier des données.",13,false));LinearLayout p=Ui.panel(this);p.addView(Ui.text(this,"Champs de travail suggérés",20,true));for(String f:sec.suggestedFields)p.addView(Ui.text(this,"• "+f,16,false));r.addView(p);r.addView(Ui.text(this,"L’application normalise les noms de colonnes, propose une correspondance, signale les champs absents et conserve un audit. Une validation humaine demeure nécessaire.",14,false));setContentView(Ui.wrap(this,r));}}
